//! Formatting helpers: time values, floats (JSON/ryu compatible) and colors.

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum TimeUnit {
    MicroSecond,
    MilliSecond,
    Second,
}

impl TimeUnit {
    pub fn parse(s: &str) -> Option<TimeUnit> {
        match s {
            "microsecond" => Some(TimeUnit::MicroSecond),
            "millisecond" => Some(TimeUnit::MilliSecond),
            "second" => Some(TimeUnit::Second),
            _ => None,
        }
    }
    pub fn unit_str(&self) -> &'static str {
        match self {
            TimeUnit::MicroSecond => "\u{b5}s",
            TimeUnit::MilliSecond => "ms",
            TimeUnit::Second => "s",
        }
    }
}

/// Pick the time unit automatically for a given amount of seconds.
pub fn auto_unit(seconds: f64) -> TimeUnit {
    if seconds < 1e-3 {
        TimeUnit::MicroSecond
    } else if seconds < 1.0 {
        TimeUnit::MilliSecond
    } else {
        TimeUnit::Second
    }
}

/// Format a duration (in seconds) using the given unit.
pub fn format_time(seconds: f64, unit: TimeUnit) -> String {
    match unit {
        TimeUnit::MicroSecond => format!("{:.1} \u{b5}s", seconds * 1e6),
        TimeUnit::MilliSecond => format!("{:.1} ms", seconds * 1e3),
        TimeUnit::Second => format!("{:.3} s", seconds),
    }
}

/// Right-align `s` in a field of `width` characters (display width).
pub fn right_align(s: &str, width: usize) -> String {
    let w = display_width(s);
    if w >= width {
        s.to_string()
    } else {
        " ".repeat(width - w) + s
    }
}

/// Display width of a string (counting unicode code points, which is what
/// hyperfine effectively does for the strings it produces).
pub fn display_width(s: &str) -> usize {
    s.chars().count()
}

// ---------------------------------------------------------------------------
// Colors
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum ColorMode {
    Always,
    Never,
}

#[derive(Clone, Copy)]
pub struct Style {
    pub color: ColorMode,
}

fn wrap(code: &str, s: &str, on: bool) -> String {
    if on {
        format!("\u{1b}[{}m{}\u{1b}[0m", code, s)
    } else {
        s.to_string()
    }
}

impl Style {
    pub fn bold(&self, s: &str) -> String {
        wrap("1", s, self.color == ColorMode::Always)
    }
    pub fn dim(&self, s: &str) -> String {
        wrap("2", s, self.color == ColorMode::Always)
    }
    pub fn green(&self, s: &str) -> String {
        wrap("32", s, self.color == ColorMode::Always)
    }
    pub fn bold_green(&self, s: &str) -> String {
        wrap("1;32", s, self.color == ColorMode::Always)
    }
    pub fn blue(&self, s: &str) -> String {
        wrap("34", s, self.color == ColorMode::Always)
    }
    pub fn cyan(&self, s: &str) -> String {
        wrap("36", s, self.color == ColorMode::Always)
    }
    pub fn magenta(&self, s: &str) -> String {
        wrap("35", s, self.color == ColorMode::Always)
    }
    pub fn yellow(&self, s: &str) -> String {
        wrap("33", s, self.color == ColorMode::Always)
    }
}

// ---------------------------------------------------------------------------
// JSON compatible float formatting (same rules as serde_json which uses ryu)
// ---------------------------------------------------------------------------

/// Format a float the way serde_json does (ryu "pretty" format).
pub fn json_float(value: f64) -> String {
    if value == 0.0 {
        return if value.is_sign_negative() {
            "-0.0".to_string()
        } else {
            "0.0".to_string()
        };
    }
    if value.is_nan() {
        return "null".to_string();
    }
    if value.is_infinite() {
        return "null".to_string();
    }
    let neg = value < 0.0;
    let v = if neg { -value } else { value };
    // Shortest round-trip decimal representation, as produced by Rust's
    // Display impl for f64 (always plain decimal notation).
    let repr = format!("{}", v);
    let (digits, kk) = decompose(&repr);
    let body = render(digits, kk);
    if neg {
        format!("-{}", body)
    } else {
        body
    }
}

/// Split a plain decimal representation into its significant digits and the
/// decimal exponent `kk` such that 10^(kk-1) <= value < 10^kk.
fn decompose(repr: &str) -> (String, i32) {
    let bytes: Vec<u8> = repr.bytes().collect();
    let mut int_digits: Vec<u8> = Vec::new();
    let mut frac_digits: Vec<u8> = Vec::new();
    let mut i = 0usize;
    while i < bytes.len() && bytes[i] != b'.' {
        int_digits.push(bytes[i]);
        i += 1;
    }
    if i < bytes.len() {
        i += 1; // skip '.'
        while i < bytes.len() {
            frac_digits.push(bytes[i]);
            i += 1;
        }
    }
    // strip leading zeros of the integer part
    let mut first_nz = 0usize;
    while first_nz < int_digits.len() && int_digits[first_nz] == b'0' {
        first_nz += 1;
    }
    let int_sig = &int_digits[first_nz..];
    if int_sig.is_empty() {
        // value < 1
        let mut nz = 0usize;
        while nz < frac_digits.len() && frac_digits[nz] == b'0' {
            nz += 1;
        }
        let sig: String = String::from_utf_lossy(&frac_digits[nz..]).to_string();
        let kk = -(nz as i32);
        (sig, kk)
    } else {
        let mut sig: Vec<u8> = int_sig.to_vec();
        // strip trailing zeros of the integer part (they are not significant)
        while sig.len() > 1 && *sig.last().unwrap() == b'0' {
            sig.pop();
        }
        let kk = sig.len() as i32;
        sig.extend_from_slice(&frac_digits);
        // strip trailing zeros that came from the fraction part
        while sig.len() > (kk as usize) && *sig.last().unwrap() == b'0' {
            sig.pop();
        }
        (String::from_utf_lossy(&sig).to_string(), kk)
    }
}

/// Apply ryu's "pretty" rendering rules.
fn render(digits: String, kk: i32) -> String {
    let length = digits.len() as i32;
    let k = kk - length; // value = digits * 10^k
    if 0 <= k && kk <= 21 {
        // 1234e7 -> 12340000000.0
        let mut s = digits.clone();
        for _ in 0..k {
            s.push('0');
        }
        s.push_str(".0");
        s
    } else if 0 < kk && kk <= 21 {
        // 1234e-2 -> 12.34
        let mut s = String::new();
        s.push_str(&digits[..kk as usize]);
        s.push('.');
        s.push_str(&digits[kk as usize..]);
        s
    } else if -5 < kk && kk <= 0 {
        // 1234e-6 -> 0.001234
        let mut s = String::from("0.");
        for _ in 0..(-kk) {
