{"command": "cd /workspace && cat > src/cli.rs <<'RSEOF'
//! Command line parsing, mimicking the behaviour (and error messages) of the
//! original clap based interface.

use crate::helptext::HELP_TEMPLATE;

pub const VERSION: &str = "hyperfine 1.20.0";

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Style {
    Auto,
    Basic,
    Full,
    NoColor,
    Color,
    None,
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum SortMethod {
    Auto,
    Command,
    MeanTime,
}

#[derive(Clone, Debug)]
pub enum OutputWhere {
    Null,
    Pipe,
    Inherit,
    File(String),
}

#[derive(Clone, Debug)]
pub enum InputWhere {
    Null,
    File(String),
}

#[derive(Clone, Debug)]
pub enum IgnoreFailure {
    AllNonZero,
    Codes(Vec<i32>),
}

/// A shell command to use for executing the benchmarked commands.
#[derive(Clone, Debug)]
pub enum Shell {
    None,
    Default(String),
}

#[derive(Clone, Debug)]
pub struct Parameters {
    pub name: String,
    pub values: Vec<String>,
}

#[derive(Clone, Debug)]
pub struct CmdOptions {
    pub warmup: u32,
    pub min_runs: u32,
    pub max_runs: Option<u32>,
    pub runs: Option<u32>,
    pub setup: Option<String>,
    pub reference: Option<String>,
    pub reference_name: Option<String>,
    pub prepare: Vec<String>,
    pub conclude: Vec<String>,
    pub cleanup: Option<String>,
    pub parameter_scan: Option<Parameters>,
    pub parameter_step_size: Option<String>,
    pub parameter_lists: Vec<Parameters>,
    pub shell: Shell,
    pub ignore_failure: Option<IgnoreFailure>,
    pub style: Style,
    pub sort: SortMethod,
    pub time_unit: Option<crate::format::TimeUnit>,
    pub export_asciidoc: Option<String>,
    pub export_csv: Option<String>,
    pub export_json: Option<String>,
    pub export_markdown: Option<String>,
    pub export_orgmode: Option<String>,
    pub show_output: bool,
    pub output: Vec<OutputWhere>,
    pub input: Vec<InputWhere>,
    pub command_names: Vec<String>,
    pub commands: Vec<String>,
}

pub struct CliError {
    pub message: String,
}

impl CliError {
    fn new(message: String) -> CliError {
        CliError { message }
    }
}

fn bin_name() -> String {
    std::env::args()
        .next()
        .map(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "hyperfine".to_string())
}

/// Print the help text (replacing the placeholder with the binary name).
pub fn print_help() {
    let text = HELP_TEMPLATE
        .trim_start_matches('\n')
        .replace("{bin}", &bin_name());
    println!("{}", text);
}

pub fn print_version() {
    println!("{}", VERSION);
}

/// Identity of every option, in the order in which they are declared. This
/// order is used when clap renders the "usage" line of an error message.
#[derive(Clone, Copy, PartialEq)]
enum OptId {
    Warmup,
    MinRuns,
    MaxRuns,
    Runs,
    Setup,
    Reference,
    ReferenceName,
    Prepare,
    Conclude,
    Cleanup,
    ParameterScan,
    ParameterStepSize,
    ParameterList,
    Shell,
    ShellNone,
    IgnoreFailure,
    Style,
    Sort,
    TimeUnit,
    ExportAsciidoc,
    ExportCsv,
    ExportJson,
    ExportMarkdown,
    ExportOrgmode,
    ShowOutput,
    Output,
    Input,
    CommandName,
}

impl OptId {
    /// How the option is rendered inside a usage line.
    fn usage_str(&self) -> &'static str {
        match self {
            OptId::Warmup => "--warmup <NUM>",
            OptId::MinRuns => "--min-runs <NUM>",
            OptId::MaxRuns => "--max-runs <NUM>",
            OptId::Runs => "--runs <NUM>",
            OptId::Setup => "--setup <CMD>",
            OptId::Reference => "--reference <CMD>",
            OptId::ReferenceName => "--reference-name <CMD>",
            OptId::Prepare => "--prepare <CMD>",
            OptId::Conclude => "--conclude <CMD>",
            OptId::Cleanup => "--cleanup <CMD>",
            OptId::ParameterScan => "--parameter-scan <VAR> <MIN> <MAX>",
            OptId::ParameterStepSize => "--parameter-step-size <DELTA>",
            OptId::ParameterList => "--parameter-list <VAR> <VALUES>",
            OptId::Shell => "--shell <SHELL>",
            OptId::ShellNone => "-N",
            OptId::IgnoreFailure => "--ignore-failure[=<MODE>]",
            OptId::Style => "--style <TYPE>",
            OptId::Sort => "--sort <METHOD>",
            OptId::TimeUnit => "--time-unit <UNIT>",
            OptId::ExportAsciidoc => "--export-asciidoc <FILE>",
            OptId::ExportCsv => "--export-csv <FILE>",
            OptId::ExportJson => "--export-json <FILE>",
            OptId::ExportMarkdown => "--export-markdown <FILE>",
            OptId::ExportOrgmode => "--export-orgmode <FILE>",
            OptId::ShowOutput => "--show-output",
            OptId::Output => "--output <WHERE>",
            OptId::Input => "--input <WHERE>",
            OptId::CommandName => "--command-name <NAME>",
        }
    }
    /// How the option is named in the "cannot be used multiple times" error.
    fn dup_str(&self) -> &'static str {
        self.usage_str()
    }
    /// How the option is rendered when the user supplied an unknown/invalid value.
    fn value_str(&self) -> &'static str {
        match self {
            OptId::ParameterScan => "--parameter-scan <VAR> <MIN> <MAX>",
            OptId::ParameterList => "--parameter-list <VAR> <VALUES>",
            OptId::IgnoreFailure => "--ignore-failure[=<MODE>]",
            OptId::Shell => "--shell <SHELL>",
            OptId::ShellNone => "-N",
            other => other.usage_str(),
        }
    }
}

fn order(id: OptId) -> usize {
    match id {
        OptId::Warmup => 0,
        OptId::MinRuns => 1,
        OptId::MaxRuns => 2,
        OptId::Runs => 3,
        OptId::Setup => 4,
        OptId::Reference => 5,
        OptId::ReferenceName => 6,
        OptId::Prepare => 7,
        OptId::Conclude => 8,
        OptId::Cleanup => 9,
        OptId::ParameterScan => 10,
        OptId::ParameterStepSize => 11,
        OptId::ParameterList => 12,
        OptId::Shell => 13,
        OptId::ShellNone => 14,
        OptId::IgnoreFailure => 15,
        OptId::Style => 16,
        OptId::Sort => 17,
        OptId::TimeUnit => 18,
        OptId::ExportAsciidoc => 19,
        OptId::ExportCsv => 20,
        OptId::ExportJson => 21,
        OptId::ExportMarkdown => 22,
        OptId::ExportOrgmode => 23,
        OptId::ShowOutput => 24,
        OptId::Output => 25,
        OptId::Input => 26,
        OptId::CommandName => 27,
    }
}

struct Parser {
    bin: String,
    used: Vec<OptId>,
    single: Vec<OptId>, // options that may only appear once
    opts: CmdOptions,
}

impl Parser {
    fn new() -> Parser {
        Parser {
            bin: bin_name(),
            used: Vec::new(),
            single: Vec::new(),
            opts: CmdOptions {
                warmup: 0,
                min_runs: 10,
                max_runs: None,
                runs: None,
                setup: None,
                reference: None,
                reference_name: None,
                prepare: Vec::new(),
                conclude: Vec::new(),
                cleanup: None,
                parameter_scan: None,
                parameter_step_size: None,
                parameter_lists: Vec::new(),
                shell: Shell::Default("/bin/sh".to_string()),
                ignore_failure: None,
                style: Style::Auto,
                sort: SortMethod::Auto,
                time_unit: None,
                export_asciidoc: None,
                export_csv: None,
                export_json: None,
                export_markdown: None,
                export_orgmode: None,
                show_output: false,
                output: Vec::new(),
                input: Vec::new(),
                command_names: Vec::new(),
                commands: Vec::new(),
            },
        }
    }

    fn mark(&mut self, id: OptId, appendable: bool) -> Result<(), CliError> {
        if appendable {
            if !self.used.contains(&id) {
                self.used.push(id);
            }
            return Ok(());
        }
        if self.single.contains(&id) {
            return Err(CliError::new(format!(
                "error: the argument '{}' cannot be used multiple times\n\nUsage: {} [OPTIONS] <command>...\n\nFor more information, try '--help'.\n",
                id.dup_str(), self.bin)));
        }
        self.single.push(id);
        self.used.push(id);
        Ok(())
    }

    fn has(&self, id: OptId) -> bool {
        self.used.contains(&id)
    }

    fn usage_line(&self, extra: &[OptId]) -> String {
        // collect used + extra required ids, ordered by declaration order
        let mut ids: Vec<OptId> = self.used.clone();
        for e in extra {
            if !ids.contains(e) {
                ids.push(*e);
            }
        }
        ids.sort_by_key(|i| order(*i));
        let mut parts: Vec<String> = ids.iter().map(|i| i.usage_str().to_string()).collect();
        parts.push("<command>...".to_string());
        format!("Usage: {} {}", self.bin, parts.join(" "))
    }

    fn full_usage(&self) -> String {
        format!("Usage: {} [OPTIONS] <command>...", self.bin)
    }

    fn err_missing(&self, missing: &[String], extra: &[OptId]) -> CliError {
        let mut msg = String::from("error: the following required arguments were not provided:\n");
        for m in missing {
            msg.push_str(&format!("  {}\n", m));
        }
        msg.push_str(&format!("\n{}\n", self.usage_line(extra)));
        msg.push_str("\nFor more information, try '--help'.\n");
        CliError::new(msg)
    }

    fn err_tip(&self, arg: &str) -> CliError {
        CliError::new(format!(
            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\n\nFor more information, try '--help'.\n",
            arg, arg, arg, self.full_usage()))
    }

    fn err_invalid_value(&self, val: &str, id: OptId, possible: &[&str]) -> CliError {
        let mut msg = format!(
            "error: invalid value '{}' for '{}'\n  [possible values: {}]\n",
            val,
            id.value_str(),
            possible.join(", ")
        );
        // clap adds a tip when a similar value exists
        if let Some(similar) = similar_value(val, possible) {
            msg.push_str(&format!("\n  tip: a similar value exists: '{}'\n", similar));
        }
        msg.push_str("\nFor more information, try '--help'.\n");
        CliError::new(msg)
    }

    fn err_need_value(&self, id: OptId) -> CliError {
        CliError::new(format!(
            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
            id.value_str()))
    }

    fn err_values(&self, id: OptId, needed: usize, got: usize) -> CliError {
        CliError::new(format!(
            "error: {} values required for '{}' but {} were provided\n\n{}\n\nFor more information, try '--help'.\n",
            needed,
            id.value_str(),
            got,
            self.full_usage()))
    }
}

fn similar_value(val: &str, possible: &[&str]) -> Option<String> {
    // crude "similar value" detection, similar to what clap does
    let mut best: Option<(usize, &str)> = None;
    for p in possible {
        let d = edit_distance(val, p);
        if d <= (val.len() / 3).max(1) {
            match best {
                Some((bd, _)) if bd <= d => {}
                _ => best = Some((d, p)),
            }
        }
    }
    best.map(|(_, s)| s.to_string())
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for i in 1..=a.len() {
        let mut cur = vec![i];
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            let v = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
            cur.push(v);
        }
        prev = cur;
    }
    prev[b.len()]
}

pub fn parse() -> Result<CmdOptions, CliError> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    parse_from(&args)
}

pub fn parse_from(args: &[String]) -> Result<CmdOptions, CliError> {
    let mut p = Parser::new();
    let mut i = 0usize;
    let mut no_more_opts = false;
    while i < args.len() {
        let arg = &args[i];
        if no_more_opts {
            p.opts.commands.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            no_more_opts = true;
            i += 1;
            continue;
        }
        if arg.starts_with("--") {
            let (name, inline) = split_inline(arg);
            i += 1;
            match name.as_str() {
                "help" => {
                    print_help();
                    std::process::exit(0);
                }
                "version" => {
                    print_version();
                    std::process::exit(0);
                }
                "warmup" => {
                    p.mark(OptId::Warmup, false)?;
                    p.opts.warmup = need_num(&mut p, &mut i, args, inline, OptId::Warmup)?;
                }
                "min-runs" => {
                    p.mark(OptId::MinRuns, false)?;
                    p.opts.min_runs = need_num(&mut p, &mut i, args, inline, OptId::MinRuns)?;
                }
                "max-runs" => {
                    p.mark(OptId::MaxRuns, false)?;
                    let v = need_num(&mut p, &mut i, args, inline, OptId::MaxRuns)?;
                    p.opts.max_runs = Some(v);
                }
                "runs" => {
                    p.mark(OptId::Runs, false)?;
                    let v = need_num(&mut p, &mut i, args, inline, OptId::Runs)?;
                    p.opts.runs = Some(v);
                }
                "setup" => {
                    p.mark(OptId::Setup, false)?;
                    p.opts.setup = Some(need_str(&mut p, &mut i, args, inline, OptId::Setup)?);
                }
                "reference" => {
                    p.mark(OptId::Reference, false)?;
                    p.opts.reference =
                        Some(need_str(&mut p, &mut i, args, inline, OptId::Reference)?);
                }
                "reference-name" => {
                    p.mark(OptId::ReferenceName, false)?;
                    p.opts.reference_name = Some(need_str(
                        &mut p,
                        &mut i,
                        args,
                        inline,
                        OptId::ReferenceName,
                    )?);
                }
                "prepare" => {
                    p.mark(OptId::Prepare, true)?;
                    p.opts.prepare
                        .push(need_str(&mut p, &mut i, args, inline, OptId::Prepare)?);
                }
                "conclude" => {
                    p.mark(OptId::Conclude, true)?;
                    p.opts.conclude
                        .push(need_str(&mut p, &mut i, args, inline, OptId::Conclude)?);
                }
                "cleanup" => {
                    p.mark(OptId::Cleanup, false)?;
                    p.opts.cleanup = Some(need_str(&mut p, &mut i, args, inline, OptId::Cleanup)?);
                }
                "parameter-scan" => {
                    p.mark(OptId::ParameterScan, false)?;
                    let vals = need_values(&mut p, &mut i, args, inline, OptId::ParameterScan, 3)?;
                    p.opts.parameter_scan = Some(Parameters {
                        name: vals[0].clone(),
                        values: vals[1..].to_vec(),
                    });
                }
                "parameter-step-size" => {
                    p.mark(OptId::ParameterStepSize, false)?;
                    p.opts.parameter_step_size = Some(need_str(
                        &mut p,
                        &mut i,
                        args,
                        inline,
                        OptId::ParameterStepSize,
                    )?);
                }
                "parameter-list" => {
                    p.mark(OptId::ParameterList, true)?;
                    let vals = need_values(&mut p, &mut i, args, inline, OptId::ParameterList, 2)?;
                    p.opts.parameter_lists.push(Parameters {
                        name: vals[0].clone(),
                        values: split_list(&vals[1]),
                    });
                }
                "shell" => {
                    if p.has(OptId::ShellNone) {
                        return Err(conflict(&mut p, OptId::ShellNone, OptId::Shell));
                    }
                    p.mark(OptId::Shell, true)?;
                    let v = need_str(&mut p, &mut i, args, inline, OptId::Shell)?;
                    p.opts.shell = parse_shell(&v);
                }
                "ignore-failure" => {
                    p.mark(OptId::IgnoreFailure, false)?;
                    let v = match inline {
                        Some(v) => Some(v),
                        None => {
                            if i < args.len() && looks_like_opt(&args[i]) {
                                None
                            } else if i < args.len() {
                                let v = args[i].clone();
                                i += 1;
                                Some(v)
                            } else {
                                None
                            }
                        }
                    };
                    p.opts.ignore_failure = Some(match v {
                        None => IgnoreFailure::AllNonZero,
                        Some(s) => {
                            if s == "all-non-zero" {
                                IgnoreFailure::AllNonZero
                            } else {
                                let mut codes = Vec::new();
                                for part in s.split(',') {
                                    match part.parse::<i32>() {
                                        Ok(c) => codes.push(c),
                                        Err(_) => {
                                            return Err(crate::runtime_error(format!(
                                                "Could not read numeric integer argument to '--ignore-failure': {}",
                                                int_error(part)
                                            )));
                                        }
                                    }
                                }
                                IgnoreFailure::Codes(codes)
                            }
                        }
                    });
                }
                "style" => {
                    p.mark(OptId::Style, false)?;
                    let v = need_str(&mut p, &mut i, args, inline, OptId::Style)?;
                    p.opts.style = match v.as_str() {
                        "auto" => Style::Auto,
                        "basic" => Style::Basic,
                        "full" => Style::Full,
                        "nocolor" => Style::NoColor,
                        "color" => Style::Color,
                        "none" => Style::None,
                        _ => {
                            return Err(p.err_invalid_value(
                                &v,
                                OptId::Style,
                                &["auto", "basic", "full", "nocolor", "color", "none"],
                            ))
                        }
                    };
                }
                "sort" => {
                    p.mark(OptId::Sort, false)?;
                    let v = need_str(&mut p, &mut i, args, inline, OptId::Sort)?;
                    p.opts.sort = match v.as_str() {
                        "auto" => SortMethod::Auto,
                        "command" => SortMethod::Command,
                        "mean-time" => SortMethod::MeanTime,
                        _ => {
                            return Err(p.err_invalid_value(
                                &v,
                                OptId::Sort,
                                &["auto", "command", "mean-time"],
                            ))
                        }
                    };
                }
                "time-unit" => {
                    p.mark(OptId::TimeUnit, false)?;
                    let v = need_str(&mut p, &mut i, args, inline, OptId::TimeUnit)?;
                    match crate::format::TimeUnit::parse(&v) {
                        Some(u) => p.opts.time_unit = Some(u),
                        None => {
                            return Err(p.err_invalid_value(
                                &v,
                                OptId::TimeUnit,
                                &["microsecond", "millisecond", "second"],
                            ))
                        }
                    }
                }
                "export-asciidoc" => {
                    p.mark(OptId::ExportAsciidoc, false)?;
                    p.opts.export_asciidoc =
                        Some(need_str(&mut p, &mut i, args, inline, OptId::ExportAsciidoc)?);
                }
                "export-csv" => {
                    p.mark(OptId::ExportCsv, false)?;
                    p.opts.export_csv =
                        Some(need_str(&mut p, &mut i, args, inline, OptId::ExportCsv)?);
                }
                "export-json" => {
                    p.mark(OptId::ExportJson, false)?;
                    p.opts.export_json =
                        Some(need_str(&mut p, &mut i, args, inline, OptId::ExportJson)?);
                }
                "export-markdown" => {
                    p.mark(OptId::ExportMarkdown, false)?;
                    p.opts.export_markdown =
                        Some(need_str(&mut p, &mut i, args, inline, OptId::ExportMarkdown)?);
                }
                "export-orgmode" => {
                    p.mark(OptId::ExportOrgmode, false)?;
                    p.opts.export_orgmode =
                        Some(need_str(&mut p, &mut i, args, inline, OptId::ExportOrgmode)?);
                }
                "show-output" => {
                    p.mark(OptId::ShowOutput, false)?;
                    p.opts.show_output = true;
                }
                "output" => {
                    p.mark(OptId::Output, true)?;
                    let v = need_str(&mut p, &mut i, args, inline, OptId::Output)?;
                    p.opts.output.push(parse_output(&v));
                }
                "input" => {
                    p.mark(OptId::Input, false)?;
                    let v = need_str(&mut p, &mut i, args, inline, OptId::Input)?;
                    p.opts.input.push(parse_input(&v));
                }
                "command-name" => {
                    p.mark(OptId::CommandName, true)?;
                    p.opts.command_names
                        .push(need_str(&mut p, &mut i, args, inline, OptId::CommandName)?);
                }
                _ => return Err(p.err_tip(arg)),
            }
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 {
            // short option(s)
            let chars: Vec<char> = arg.chars().skip(1).collect();
            let mut ci = 0usize;
            let mut consumed_rest = false;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                match c {
                    'h' => {
                        print_help();
                        std::process::exit(0);
                    }
                    'V' => {
                        print_version();
                        std::process::exit(0);
                    }
                    'w' => {
                        p.mark(OptId::Warmup, false)?;
                        p.opts.warmup = short_num(&mut p, &mut i, args, &chars[ci..], OptId::Warmup)?;
                        consumed_rest = true;
                    }
                    'm' => {
                        p.mark(OptId::MinRuns, false)?;
                        p.opts.min_runs =
                            short_num(&mut p, &mut i, args, &chars[ci..], OptId::MinRuns)?;
                        consumed_rest = true;
                    }
                    'M' => {
                        p.mark(OptId::MaxRuns, false)?;
                        let v = short_num(&mut p, &mut i, args, &chars[ci..], OptId::MaxRuns)?;
                        p.opts.max_runs = Some(v);
                        consumed_rest = true;
                    }
                    'r' => {
                        p.mark(OptId::Runs, false)?;
                        let v = short_num(&mut p, &mut i, args, &chars[ci..], OptId::Runs)?;
                        p.opts.runs = Some(v);
                        consumed_rest = true;
                    }
                    's' => {
                        p.mark(OptId::Setup, false)?;
                        p.opts.setup =
                            Some(short_str(&mut p, &mut i, args, &chars[ci..], OptId::Setup)?);
                        consumed_rest = true;
                    }
                    'p' => {
                        p.mark(OptId::Prepare, true)?;
                        p.opts.prepare.push(short_str(
                            &mut p,
                            &mut i,
                            args,
                            &chars[ci..],
                            OptId::Prepare,
                        )?);
                        consumed_rest = true;
                    }
                    'C' => {
                        p.mark(OptId::Conclude, true)?;
                        p.opts.conclude.push(short_str(
                            &mut p,
                            &mut i,
                            args,
                            &chars[ci..],
                            OptId::Conclude,
                        )?);
                        consumed_rest = true;
                    }
                    'c' => {
                        p.mark(OptId::Cleanup, false)?;
                        p.opts.cleanup =
                            Some(short_str(&mut p, &mut i, args, &chars[ci..], OptId::Cleanup)?);
                        consumed_rest = true;
                    }
                    'P' => {
                        p.mark(OptId::ParameterScan, false)?;
                        let vals = short_values(
                            &mut p,
                            &mut i,
                            args,
                            &chars[ci..],
                            OptId::ParameterScan,
                            3,
                        )?;
                        p.opts.parameter_scan = Some(Parameters {
                            name: vals[0].clone(),
                            values: vals[1..].to_vec(),
                        });
                        consumed_rest = true;
                    }
                    'D' => {
                        p.mark(OptId::ParameterStepSize, false)?;
                        p.opts.parameter_step_size = Some(short_str(
                            &mut p,
                            &mut i,
                            args,
                            &chars[ci..],
                            OptId::ParameterStepSize,
                        )?);
                        consumed_rest = true;
                    }
                    'L' => {
                        p.mark(OptId::ParameterList, true)?;
                        let vals = short_values(
                            &mut p,
                            &mut i,
                            args,
                            &chars[ci..],
                            OptId::ParameterList,
                            2,
                        )?;
                        p.opts.parameter_lists.push(Parameters {
                            name: vals[0].clone(),
                            values: split_list(&vals[1]),
                        });
                        consumed_rest = true;
                    }
                    'S' => {
                        if p.has(OptId::ShellNone) {
                            return Err(conflict(&mut p, OptId::ShellNone, OptId::Shell));
                        }
                        p.mark(OptId::Shell, true)?;
                        let v = short_str(&mut p, &mut i, args, &chars[ci..], OptId::Shell)?;
                        p.opts.shell = parse_shell(&v);
                        consumed_rest = true;
                    }
                    'N' => {
                        if p.has(OptId::Shell) {
                            return Err(conflict(&mut p, OptId::Shell, OptId::ShellNone));
                        }
                        p.mark(OptId::ShellNone, false)?;
                        p.opts.shell = Shell::None;
                    }
                    'i' => {
                        p.mark(OptId::IgnoreFailure, false)?;
                        let rest: String = chars[ci..].iter().collect();
                        let v = if !rest.is_empty() {
                            let r = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            ci = chars.len();
                            Some(r)
                        } else if i < args.len() && !looks_like_opt(&args[i]) {
                            let v = args[i].clone();
                            i += 1;
                            Some(v)
                        } else {
                            None
                        };
                        p.opts.ignore_failure = Some(match v {
                            None => IgnoreFailure::AllNonZero,
                            Some(s) => {
                                if s == "all-non-zero" {
                                    IgnoreFailure::AllNonZero
                                } else {
                                    let mut codes = Vec::new();
                                    for part in s.split(',') {
                                        match part.parse::<i32>() {
                                            Ok(cc) => codes.push(cc),
                                            Err(_) => {
                                                return Err(crate::runtime_error(format!(
                                                    "Could not read numeric integer argument to '--ignore-failure': {}",
                                                    int_error(part)
                                                )));
                                            }
                                        }
                                    }
                                    IgnoreFailure::Codes(codes)
                                }
                            }
                        });
                        consumed_rest = true;
                    }
                    'u' => {
                        p.mark(OptId::TimeUnit, false)?;
                        let v = short_str(&mut p, &mut i, args, &chars[ci..], OptId::TimeUnit)?;
                        match crate::format::TimeUnit::parse(&v) {
                            Some(u) => p.opts.time_unit = Some(u),
                            None => {
                                return Err(p.err_invalid_value(
                                    &v,
                                    OptId::TimeUnit,
                                    &["microsecond", "millisecond", "second"],
                                ))
                            }
                        }
                        consumed_rest = true;
                    }
                    'n' => {
                        p.mark(OptId::CommandName, true)?;
                        p.opts.command_names.push(short_str(
                            &mut p,
                            &mut i,
                            args,
                            &chars[ci..],
                            OptId::CommandName,
                        )?);
                        consumed_rest = true;
                    }
                    _ => return Err(p.err_tip(arg)),
                }
                if consumed_rest {
                    break;
                }
            }
            i += 1;
            continue;
        }
        p.opts.commands.push(arg.clone());
        i += 1;
    }

    // required arguments
    let mut missing: Vec<String> = Vec::new();
    let mut extra: Vec<OptId> = Vec::new();
    if p.opts.commands.is_empty() {
        missing.push("<command>...".to_string());
    }
    if p.has(OptId::ParameterStepSize) && !p.has(OptId::ParameterScan) {
        missing.push(OptId::ParameterScan.usage_str().to_string());
        extra.push(OptId::ParameterScan);
    }
    if p.has(OptId::ReferenceName) && !p.has(OptId::Reference) {
        missing.push(OptId::Reference.usage_str().to_string());
        extra.push(OptId::Reference);
    }
    if !missing.is_empty() {
        return Err(p.err_missing(&missing, &extra));
    }
    if p.has(OptId::ParameterScan) && p.has(OptId::ParameterList) {
        return Err(conflict(
            &mut p,
            OptId::ParameterScan,
            OptId::ParameterList,
        ));
    }
    Ok(p.opts)
}

fn conflict(p: &mut Parser, used: OptId, other: OptId) -> CliError {
    let _ = other;
    if !p.used.contains(&used) {
        p.used.push(used);
    }
    CliError::new(format!(
        "error: the argument '{}' cannot be used with '{}'\n\n{}\n\nFor more information, try '--help'.\n",
        other_name(used),
        other_name(used_other(used)),
        p.usage_line(&[])
    ))
}

fn other_name(id: OptId) -> &'static str {
    id.usage_str()
}
fn used_other(id: OptId) -> OptId {
    id
}

fn split_inline(arg: &str) -> (String, Option<String>) {
    match arg.find('=') {
        Some(idx) => (arg[2..idx].to_string(), Some(arg[idx + 1..].to_string())),
        None => (arg[2..].to_string(), None),
    }
}

fn looks_like_opt(s: &str) -> bool {
    s.starts_with('-') && s.len() > 1
}

fn need_num(
    p: &mut Parser,
    i: &mut usize,
    args: &[String],
    inline: Option<String>,
    id: OptId,
) -> Result<u32, CliError> {
    let s = match inline {
        Some(v) => v,
        None => {
            if *i < args.len() {
                let v = args[*i].clone();
                *i += 1;
                v
            } else {
                return Err(p.err_need_value(id));
            }
        }
    };
    match s.parse::<u32>() {
        Ok(v) => Ok(v),
        Err(_) => Err(crate::runtime_error(format!(
            "Could not read numeric integer argument to '{}': {}",
            id.value_str(),
            int_error(&s)
        ))),
    }
}

fn short_num(
    p: &mut Parser,
    i: &mut usize,
    args: &[String],
    rest: &[char],
    id: OptId,
) -> Result<u32, CliError> {
    if !rest.is_empty() {
        let s: String = rest.iter().collect();
        return match s.parse::<u32>() {
            Ok(v) => Ok(v),
            Err(_) => Err(crate::runtime_error(format!(
                "Could not read numeric integer argument to '{}': {}",
                id.value_str(),
                int_error(&s)
            ))),
        };
    }
    need_num(p, i, args, None, id)
}

fn need_str(
    p: &mut Parser,
    i: &mut usize,
    args: &[String],
    inline: Option<String>,
    id: OptId,
) -> Result<String, CliError> {
    match inline {
        Some(v) => Ok(v),
        None => {
            if *i < args.len() {
                let v = args[*i].clone();
                *i += 1;
                Ok(v)
            } else {
                Err(p.err_need_value(id))
            }
        }
    }
}

fn short_str(
    p: &mut Parser,
    i: &mut usize,
    args: &[String],
    rest: &[char],
    id: OptId,
) -> Result<String, CliError> {
    if !rest.is_empty() {
        return Ok(rest.iter().collect());
    }
    need_str(p, i, args, None, id)
}

fn need_values(
    p: &mut Parser,
    i: &mut usize,
    args: &[String],
    inline: Option<String>,
    id: OptId,
    needed: usize,
) -> Result<Vec<String>, CliError> {
    let mut vals: Vec<String> = Vec::new();
    if let Some(v) = inline {
        vals.push(v);
    }
    while vals.len() < needed {
        if *i < args.len() && !looks_like_opt(&args[*i]) {
            vals.push(args[*i].clone());
            *i += 1;
        } else if vals.is_empty() {
            return Err(p.err_need_value(id));
        } else {
            break;
        }
    }
    if vals.len() < needed {
        return Err(p.err_values(id, needed, vals.len()));
    }
    Ok(vals)
}

fn short_values(
    p: &mut Parser,
    i: &mut usize,
    args: &[String],
    rest: &[char],
    id: OptId,
    needed: usize,
) -> Result<Vec<String>, CliError> {
    let mut vals: Vec<String> = Vec::new();
    if !rest.is_empty() {
        vals.push(rest.iter().collect());
    }
    while vals.len() < needed {
        if *i < args.len() && !looks_like_opt(&args[*i]) {
            vals.push(args[*i].clone());
            *i += 1;
        } else {
            break;
        }
    }
    if vals.len() < needed {
        if vals.is_empty() {
            return Err(p.err_need_value(id));
        }
        return Err(p.err_values(id, needed, vals.len()));
    }
    Ok(vals)
}

fn split_list(s: &str) -> Vec<String> {
    s.split(',').map(|x| x.to_string()).collect()
}

fn parse_shell(s: &str) -> Shell {
    match s {
        "none" => Shell::None,
        "default" => Shell::Default("/bin/sh".to_string()),
        _ => Shell::Default(s.to_string()),
    }
}

fn parse_output(s: &str) -> OutputWhere {
    match s {
        "null" => OutputWhere::Null,
        "pipe" => OutputWhere::Pipe,
        "inherit" => OutputWhere::Inherit,
        _ => OutputWhere::File(s.to_string()),
    }
}

fn parse_input(s: &str) -> InputWhere {
    match s {
        "null" => InputWhere::Null,
        _ => InputWhere::File(s.to_string()),
    }
}

fn int_error(s: &str) -> String {
    if s.is_empty() {
        "cannot parse integer from empty string".to_string()
    } else if s.parse::<i64>().is_err() {
        // distinguish between an invalid digit and out of range
        let trimmed = s.strip_prefix('+').unwrap_or(s);
        if trimmed.chars().all(|c| c.is_ascii_digit()) && !trimmed.is_empty() {
            "number too large to fit in target type".to_string()
        } else {
            "invalid digit found in string".to_string()
        }
    } else {
        "invalid digit found in string".to_string()
    }
}
