{"command": "cd /workspace && cat > src/bench.rs <<'RSEOF'
//! Benchmark execution engine.

use crate::cli::{CmdOptions, IgnoreFailure, InputWhere, OutputWhere, Shell};
use std::io::{Read, Write};
use std::process::{Child, Command, Stdio};
use std::time::Instant;

#[derive(Clone, Debug)]
pub struct BenchmarkResult {
    /// Name as displayed in the output (may be a `--command-name`).
    pub name: String,
    /// Raw command that was benchmarked.
    pub command: String,
    pub mean: f64,
    pub stddev: f64,
    pub median: f64,
    pub user: f64,
    pub system: f64,
    pub min: f64,
    pub max: f64,
    pub times: Vec<f64>,
    pub memory: Vec<u64>,
    pub exit_codes: Vec<i32>,
}

pub struct RunOutcome {
    pub time: f64,
    pub user: f64,
    pub system: f64,
    pub maxrss: u64,
    pub exit_code: i32,
}

pub fn runtime_error(msg: String) -> crate::cli::CliError {
    crate::cli::CliError { message: format!("Error: {}\n", msg) }
}

fn shell_argv(shell: &str, cmd: &str) -> Vec<String> {
    let mut parts = crate::shlex::split(shell).unwrap_or_else(|| vec![shell.to_string()]);
    parts.push("-c".to_string());
    parts.push(cmd.to_string());
    parts
}

/// Substitute `{name}` placeholders.
pub fn substitute(cmd: &str, params: &[(String, String)]) -> String {
    let mut out = cmd.to_string();
    for (k, v) in params {
        out = out.replace(&format!("{{{}}}", k), v);
    }
    out
}

fn stdio_for_output(where_: &OutputWhere, show: bool) -> Stdio {
    match where_ {
        OutputWhere::Null => Stdio::null(),
        OutputWhere::Pipe => Stdio::piped(),
        OutputWhere::Inherit => Stdio::inherit(),
        OutputWhere::File(f) => match std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(f)
        {
            Ok(file) => Stdio::from(file),
            Err(_) => Stdio::null(),
        },
    }
    .into_show(show)
}

trait IntoShow {
    fn into_show(self, show: bool) -> Stdio;
}
impl IntoShow for Stdio {
    fn into_show(self, show: bool) -> Stdio {
        if show {
            Stdio::inherit()
        } else {
            self
        }
    }
}

fn stdio_for_input(where_: &InputWhere) -> Stdio {
    match where_ {
        InputWhere::Null => Stdio::null(),
        InputWhere::File(f) => match std::fs::File::open(f) {
            Ok(file) => Stdio::from(file),
            Err(_) => Stdio::null(),
        },
    }
}

/// Run a single command and measure it.
pub fn execute(
    argv: &[String],
    input: &InputWhere,
    output: &OutputWhere,
    show_output: bool,
) -> Result<RunOutcome, String> {
    let mut cmd = Command::new(&argv[0]);
    cmd.args(&argv[1..]);
    cmd.stdin(stdio_for_input(input));
    cmd.stdout(stdio_for_output(output, show_output));
    cmd.stderr(stdio_for_output(output, show_output));

    let before = crate::sys::children_rusage();
    let start = Instant::now();
    let mut child: Child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(format!("{}", e)),
    };
    let pid = child.id() as i32;
    // drain the pipe if requested
    let mut pipe_out = child.stdout.take();
    let mut pipe_err = child.stderr.take();
    let _ = &mut pipe_out;
    let _ = &mut pipe_err;
    let (status, ru) = loop {
        let (status, ru) = crate::sys::wait4_rusage(pid);
        if status >= 0 {
            break (status, ru);
        }
        // wait4 failed: fall back to waiting on the child handle
        match child.try_wait() {
            Ok(Some(_)) => {
                let ru = crate::sys::children_rusage();
                break (crate::sys::exit_code(0).unwrap_or(-1), ru);
            }
            Ok(None) => continue,
            Err(_) => continue,
        }
    };
    let elapsed = start.elapsed();
    if let Some(mut o) = pipe_out {
        let mut buf = [0u8; 8192];
        while o.read(&mut buf).unwrap_or(0) > 0 {}
    }
    if let Some(mut e) = pipe_err {
        let mut buf = [0u8; 8192];
        while e.read(&mut buf).unwrap_or(0) > 0 {}
    }
    let after = crate::sys::children_rusage();
    let user = (ru.ru_utime.tv_sec as f64) + (ru.ru_utime.tv_usec as f64) / 1e6;
    let system = (ru.ru_stime.tv_sec as f64) + (ru.ru_stime.tv_usec as f64) / 1e6;
    let _ = before;
    let _ = after;
    Ok(RunOutcome {
        time: elapsed.as_secs_f64(),
        user,
        system,
        maxrss: (ru.ru_maxrss.max(0) as u64) * 1024,
        exit_code: crate::sys::exit_code(status).unwrap_or(-1),
    })
}

pub struct ShellSpawn {
    pub time: f64,
    pub user: f64,
    pub system: f64,
}

/// Measure the shell spawning time by running the shell 50 times with an empty
/// command.  Returns None when the measurement could not be performed.
pub fn measure_shell_spawn(shell_argv: &[String], opts: &CmdOptions) -> Result<ShellSpawn, String> {
    let mut argv: Vec<String> = shell_argv.to_vec();
    argv.push("-c".to_string());
    argv.push(String::new());
    let mut times: Vec<f64> = Vec::new();
    let mut users: Vec<f64> = Vec::new();
    let mut systems: Vec<f64> = Vec::new();
    for _ in 0..50 {
        match execute(&argv, &InputWhere::Null, &OutputWhere::Null, false) {
            Ok(o) => {
                times.push(o.time);
                users.push(o.user);
                systems.push(o.system);
            }
            Err(_) => {
                return Err(format!(
                    "Could not measure shell execution time. Make sure you can run '{} -c \"\"'.",
                    crate::shlex::join(shell_argv)
                ))
            }
        }
    }
    let _ = opts;
    let n = times.len() as f64;
    Ok(ShellSpawn {
        time: times.iter().sum::<f64>() / n,
        user: users.iter().sum::<f64>() / n,
        system: systems.iter().sum::<f64>() / n,
    })
}

pub fn compute_stats(mut times: Vec<f64>) -> (f64, f64, f64, f64, f64) {
    times.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let n = times.len() as f64;
    let mean = times.iter().sum::<f64>() / n;
    let median = if times.len() % 2 == 1 {
        times[times.len() / 2]
    } else {
        (times[times.len() / 2 - 1] + times[times.len() / 2]) / 2.0
    };
    let var = if times.len() > 1 {
        let s: f64 = times.iter().map(|t| (t - mean) * (t - mean)).sum();
        s / (times.len() - 1) as f64
    } else {
        0.0
    };
    let stddev = var.sqrt();
    (mean, stddev, median, times[0], times[times.len() - 1])
}

#[derive(Clone, Debug, PartialEq)]
pub enum Warning {
    FastCommand,
    SlowFirstRun(String),
    Outliers,
    IgnoredExitCode,
}

/// Determine the warnings for a finished benchmark.
pub fn get_warnings(
    timings: &[f64],
    mean: f64,
    shell_used: bool,
    non_zero_exit: bool,
) -> Vec<Warning> {
    let mut w: Vec<Warning> = Vec::new();
    if shell_used && mean < 0.005 {
        w.push(Warning::FastCommand);
    }
    if timings.len() > 3 {
        // first run significantly slower than the rest?
        if let Some(v) = slow_first_run(timings) {
            w.push(Warning::SlowFirstRun(v));
        }
    }
    if mean >= 0.005 {
        if has_outliers(timings) {
            w.push(Warning::Outliers);
        }
    }
    if non_zero_exit {
        w.push(Warning::IgnoredExitCode);
    }
    w
}

fn slow_first_run(timings: &[f64]) -> Option<String> {
    if timings.len() < 4 {
        return None;
    }
    let rest: Vec<f64> = timings[1..].to_vec();
    let rest_min = rest.iter().cloned().fold(f64::INFINITY, f64::min);
    if timings[0] > rest_min * 1.0 + 0.0 && timings[0] > rest_min {
        Some(crate::format::format_time(
            timings[0],
            crate::format::auto_unit(timings[0]),
        ))
    } else {
        None
    }
}

pub fn has_outliers(timings: &[f64]) -> bool {
    let n = timings.len();
    if n < 3 {
        return false;
    }
    let mean = timings.iter().sum::<f64>() / n as f64;
    let var: f64 = timings.iter().map(|t| (t - mean) * (t - mean)).sum() / (n - 1) as f64;
    let stddev = var.sqrt();
    if stddev <= 0.0 {
        return false;
    }
    let threshold = (n - 1) as f64 / (n as f64).sqrt();
    timings
        .iter()
        .any(|t| (t - mean).abs() > threshold * stddev)
}
RSEOF
echo ok"}

