/// Measure the shell spawning time by running the shell 50 times with an empty
/// command.  Returns None when the measurement could not be performed.
pub fn measure_shell_spawn(shell_argv: &[String], opts: &CmdOptions) -> Result<ShellSpawn, String> {
    let mut argv: Vec<String> = shell_argv.to_vec();
    argv.push("-c".to_string());
    argv.push(String::new());
    let mut times: Vec<f64> = Vec::new();
    let mut users: Vec<f64> = Vec::new();
    let mut systems: Vec<f64> = Vec::new();
    for _ in 0..50 {
        match execute(&argv, &InputWhere::Null, &OutputWhere::Null, false) {
            Ok(o) => {
                times.push(o.time);
                users.push(o.user);
                systems.push(o.system);
            }
            Err(_) => {
                return Err(format!(
                    "Could not measure shell execution time. Make sure you can run '{} -c \"\"'.",
                    crate::shlex::join(shell_argv)
                ))
            }
        }
    }
    let _ = opts;
    let n = times.len() as f64;
    Ok(ShellSpawn {
        time: times.iter().sum::<f64>() / n,
        user: users.iter().sum::<f64>() / n,
        system: systems.iter().sum::<f64>() / n,
    })
}

pub fn compute_stats(mut times: Vec<f64>) -> (f64, f64, f64, f64, f64) {
    times.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let n = times.len() as f64;
    let mean = times.iter().sum::<f64>() / n;
    let median = if times.len() % 2 == 1 {
        times[times.len() / 2]
    } else {
        (times[times.len() / 2 - 1] + times[times.len() / 2]) / 2.0
    };
    let var = if times.len() > 1 {
        let s: f64 = times.iter().map(|t| (t - mean) * (t - mean)).sum();
        s / (times.len() - 1) as f64
    } else {
        0.0
    };
    let stddev = var.sqrt();
    (mean, stddev, median, times[0], times[times.len() - 1])
}

#[derive(Clone, Debug, PartialEq)]
pub enum Warning {
    FastCommand,
    SlowFirstRun(String),
    Outliers,
    IgnoredExitCode,
}

/// Determine the warnings for a finished benchmark.
pub fn get_warnings(
    timings: &[f64],
    mean: f64,
    shell_used: bool,
    non_zero_exit: bool,
) -> Vec<Warning> {
    let mut w: Vec<Warning> = Vec::new();
    if shell_used && mean < 0.005 {
        w.push(Warning::FastCommand);
    }
    if timings.len() > 3 {
        // first run significantly slower than the rest?
        if let Some(v) = slow_first_run(timings) {
            w.push(Warning::SlowFirstRun(v));
        }
    }
    if mean >= 0.005 {
        if has_outliers(timings) {
            w.push(Warning::Outliers);
        }
    }
    if non_zero_exit {
        w.push(Warning::IgnoredExitCode);
    }
    w
}

fn slow_first_run(timings: &[f64]) -> Option<String> {
    if timings.len() < 4 {
        return None;
    }
    let rest: Vec<f64> = timings[1..].to_vec();
    let rest_min = rest.iter().cloned().fold(f64::INFINITY, f64::min);
    if timings[0] > rest_min * 1.0 + 0.0 && timings[0] > rest_min {
        Some(crate::format::format_time(
            timings[0],
            crate::format::auto_unit(timings[0]),
        ))
    } else {
        None
    }
}

pub fn has_outliers(timings: &[f64]) -> bool {
    let n = timings.len();
    if n < 3 {
        return false;
    }
    let mean = timings.iter().sum::<f64>() / n as f64;
    let var: f64 = timings.iter().map(|t| (t - mean) * (t - mean)).sum() / (n - 1) as f64;
    let stddev = var.sqrt();
    if stddev <= 0.0 {
        return false;
    }
    let threshold = (n - 1) as f64 / (n as f64).sqrt();
    timings
        .iter()
        .any(|t| (t - mean).abs() > threshold * stddev)
}
