//! Minimal POSIX-like word splitting (used for `--shell` and `--shell=none`).

pub fn split(s: &str) -> Option<Vec<String>> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut has = false;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            ' ' | '\t' | '\n' | '\r' => {
                if has {
                    out.push(std::mem::take(&mut cur));
                    has = false;
                }
            }
            '\\' => match chars.next() {
                Some(n) => {
                    cur.push(n);
                    has = true;
                }
                None => return None,
            },
            '\'' => {
                has = true;
                loop {
                    match chars.next() {
                        Some('\'') => break,
                        Some(c2) => cur.push(c2),
                        None => return None,
                    }
                }
            }
            '"' => {
                has = true;
                loop {
                    match chars.next() {
                        Some('"') => break,
                        Some('\\') => match chars.next() {
                            Some(n) => {
                                if n == '"' || n == '\\' || n == '$' || n == '`' {
                                    cur.push(n);
                                } else {
                                    cur.push('\\');
                                    cur.push(n);
                                }
                            }
                            None => return None,
                        },
                        Some(c2) => cur.push(c2),
                        None => return None,
                    }
                }
            }
            _ => {
                cur.push(c);
                has = true;
            }
        }
    }
    if has {
        out.push(cur);
    }
    Some(out)
}

/// Join words back into a single string (for error messages).
pub fn join(words: &[String]) -> String {
    let mut out = String::new();
    for (i, w) in words.iter().enumerate() {
        if i > 0 {
            out.push(' ');
        }
        if w.is_empty() || w.chars().any(|c| c.is_whitespace() || c == '"' || c == '\'') {
            out.push('"');
            for c in w.chars() {
                if c == '"' {
                    out.push('\\');
                }
                out.push(c);
            }
            out.push('"');
        } else {
            out.push_str(w);
        }
    }
    out
}
