pub fn print_header(style: &Style, index: usize, name: &str) {
    println!(
        "{} {}{}: {}",
        style.bold("Benchmark "),
        style.bold(&index.to_string()),
        "",
        name
    );
}

pub fn print_summary(
    style: &Style,
    result: &BenchmarkResult,
    time_unit: TimeUnit,
    one_run: bool,
) {
    let mean_str = format_time(result.mean, time_unit);
    let min_str = format_time(result.min, time_unit);
    let max_str = format_time(result.max, time_unit);
