{"command": "cd /workspace && cat > src/export.rs <<'RSEOF'
//! Export of the benchmark results to CSV, JSON, Markdown, AsciiDoc and org-mode.

use crate::bench::BenchmarkResult;
use crate::cli::SortMethod;
use crate::format::{auto_unit, format_time, json_float, TimeUnit};

pub fn csv_escape(s: &str) -> String {
    if s.contains(',') || s.contains('"') || s.contains('\n') {
        format!("\"{}\"", s.replace('"', "\"\""))
    } else {
        s.to_string()
    }
}

pub fn export_csv(path: &str, results: &[BenchmarkResult]) -> Result<(), String> {
    let mut out = String::from("command,mean,stddev,median,user,system,min,max\n");
    for r in results {
        out.push_str(&format!(
            "{},{},{},{},{},{},{},{}\n",
            csv_escape(&r.command),
            json_float(r.mean),
            json_float(r.stddev),
            json_float(r.median),
            json_float(r.user),
            json_float(r.system),
            json_float(r.min),
            json_float(r.max)
        ));
    }
    write_file(path, &out)
}

fn json_escape(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn export_json(path: &str, results: &[BenchmarkResult]) -> Result<(), String> {
    let mut out = String::from("{\n  \"results\": [\n");
    for (i, r) in results.iter().enumerate() {
        out.push_str("    {\n");
        out.push_str(&format!("      \"command\": {},\n", json_escape(&r.command)));
        out.push_str(&format!("      \"mean\": {},\n", json_float(r.mean)));
        out.push_str(&format!("      \"stddev\": {},\n", json_float(r.stddev)));
        out.push_str(&format!("      \"median\": {},\n", json_float(r.median)));
        out.push_str(&format!("      \"user\": {},\n", json_float(r.user)));
        out.push_str(&format!("      \"system\": {},\n", json_float(r.system)));
        out.push_str(&format!("      \"min\": {},\n", json_float(r.min)));
        out.push_str(&format!("      \"max\": {},\n", json_float(r.max)));
        out.push_str("      \"times\": [\n");
        for (j, t) in r.times.iter().enumerate() {
            out.push_str(&format!("        {}", json_float(*t)));
            if j + 1 < r.times.len() {
                out.push(',');
            }
            out.push('\n');
        }
        out.push_str("      ],\n");
        out.push_str("      \"memory_usage_byte\": [\n");
        for (j, m) in r.memory.iter().enumerate() {
            out.push_str(&format!("        {}", m));
            if j + 1 < r.memory.len() {
                out.push(',');
            }
            out.push('\n');
        }
        out.push_str("      ],\n");
        out.push_str("      \"exit_codes\": [\n");
        for (j, e) in r.exit_codes.iter().enumerate() {
            out.push_str(&format!("        {}", e));
            if j + 1 < r.exit_codes.len() {
                out.push(',');
            }
            out.push('\n');
        }
        out.push_str("      ]\n");
        out.push_str("    }");
        if i + 1 < results.len() {
            out.push(',');
        }
        out.push('\n');
    }
    out.push_str("  ]\n}\n");
    write_file(path, &out)
}

fn unit_for(results: &[BenchmarkResult], forced: Option<TimeUnit>) -> TimeUnit {
    match forced {
        Some(u) => u,
        None => auto_unit(results.first().map(|r| r.mean).unwrap_or(0.0)),
    }
}

