    results: &[BenchmarkResult],
    time_unit: Option<TimeUnit>,
    sort: SortMethod,
) -> Result<(), String> {
    let unit = unit_for(results, time_unit);
    let relative = crate::out::relative_to_fastest(results);
    let mut out = String::new();
    out.push_str(&format!(
        "| Command  |  Mean [{}] |  Min [{}] |  Max [{}] |  Relative |\n",
        unit.unit_str(),
        unit.unit_str(),
        unit.unit_str()
    ));
    out.push_str("|--+--+--+--+--|\n");
    for i in sorted_results(results, sort) {
        let r = &results[i];
        let rel = &relative[i];
        let rel_str = if rel.uncertainty > 0.0 {
            format!("{:.2} \u{b1} {:.2}", rel.factor, rel.uncertainty)
        } else {
            format!("{:.2}", rel.factor)
        };
        out.push_str(&format!(
            "| ={}=  |  {} |  {} |  {} |  {} |\n",
            r.command.replace('|', "\\|"),
            mean_cell(r.mean, r.stddev, unit),
            value_cell(r.min, unit),
            value_cell(r.max, unit),
            rel_str
        ));
    }
    write_file(path, &out)
}

pub fn write_file(path: &str, content: &str) -> Result<(), String> {
    match std::fs::File::create(path) {
        Ok(mut f) => {
            if let Err(e) = f.write_all(content.as_bytes()) {
                return Err(format!("Could not create export file '{}': {}", path, e));
            }
            Ok(())
        }
        Err(e) => Err(format!("Could not create export file '{}': {}", path, e)),
    }
}

pub fn format_time_for_export(seconds: f64, unit: TimeUnit) -> String {
    format_time(seconds, unit)
}
