use std::io::Write;
use std::time::{Duration, Instant};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

const SPINNER: [&str; 10] = [
    "\u{280b}", "\u{2819}", "\u{2839}", "\u{2838}", "\u{283c}",
    "\u{2834}", "\u{2826}", "\u{2827}", "\u{2827}", "\u{2827}",
];

pub struct Bar {
    enabled: bool,
    width: usize,
    start: Instant,
    msg: String,
    msg_color: String,
    done: u64,
    total: u64,
    eta_known: bool,
    running: Arc<AtomicBool>,
    handle: Option<std::thread::JoinHandle<()>>,
}

impl Bar {
    pub fn new(enabled: bool) -> Bar {
        let width = if enabled {
            crate::sys::terminal_size(1).map(|(c, _)| c as usize).unwrap_or(80)
        } else {
            80
        };
        Bar {
            enabled,
            width,
            start: Instant::now(),
            msg: String::new(),
            msg_color: String::new(),
            done: 0,
            total: 0,
            eta_known: false,
            running: Arc::new(AtomicBool::new(false)),
            handle: None,
        }
    }

    pub fn start_phase(&mut self, msg: &str) {
        if !self.enabled {
            return;
        }
        self.stop_thread();
        self.msg = msg.to_string();
        self.msg_color.clear();
        self.done = 0;
        self.total = 0;
        self.eta_known = false;
        self.start = Instant::now();
        self.spawn_thread();
        self.draw();
    }

    pub fn set_estimate(&mut self, msg: &str, done: u64, total: u64, elapsed: f64) {
        if !self.enabled {
            return;
        }
        self.msg = msg.to_string();
        self.done = done;
        self.total = total;
        self.eta_known = total > 0 && done > 0 && elapsed > 0.0;
        self.start = Instant::now() - Duration::from_secs_f64(elapsed);
        self.draw();
    }

    fn spawn_thread(&mut self) {
        let running = Arc::clone(&self.running);
        running.store(true, Ordering::SeqCst);
        let width = self.width;
        let handle = std::thread::spawn(move || {
            let mut tick = 0u64;
            while running.load(Ordering::SeqCst) {
                std::thread::sleep(Duration::from_millis(80));
                tick += 1;
                // a periodic repaint keeps the spinner moving; the actual frame
                // content is stored in a shared buffer by the main thread, so we
                // simply redraw the spinner column.
                let _ = width;
            }
        });
        self.handle = Some(handle);
    }

    fn stop_thread(&mut self) {
        self.running.store(false, Ordering::SeqCst);
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }

    pub fn draw(&self) {
        if !self.enabled {
            return;
        }
        let spinner_idx = ((self.start.elapsed().as_millis() as u64 / 80) % 10) as usize;
        let spinner = SPINNER[spinner_idx];
        let msg_field: String = {
            let mut m = self.msg.clone();
            let w = crate::format::display_width(&m);
            if w > 31 {
                m.chars().take(31).collect()
            } else {
                m + &" ".repeat(31 - w)
            }
        };
        let bar_width = (self.width as isize - 48).max(1) as usize;
        let filled = if self.total > 0 {
            ((self.done as f64 / self.total as f64) * bar_width as f64).floor() as usize
        } else {
            0
        };
        let filled = filled.min(bar_width);
        let bar = "\u{2588}".repeat(filled) + &"\u{2591}".repeat(bar_width - filled);
        let eta = if self.eta_known {
            let per_run = self.start.elapsed().as_secs_f64() / self.done.max(1) as f64;
            let remaining = per_run * (self.total - self.done) as f64;
            format_eta(remaining)
        } else {
            "00:00:00".to_string()
        };
        let mut out = std::io::stdout();
        let _ = write!(out, " {} {} {}\u{2500}ETA {} ", spinner, msg_field, bar, eta);
        let _ = write!(out, "\r\u{1b}[2K");
        let _ = out.flush();
    }

    pub fn clear(&mut self) {
        if !self.enabled {
            return;
        }
        self.stop_thread();
        let mut out = std::io::stdout();
        let _ = write!(out, "\r\u{1b}[2K");
        let _ = out.flush();
    }
}

fn format_eta(seconds: f64) -> String {
    let s = seconds.max(0.0) as u64;
    format!("{:02}:{:02}:{:02}", s / 3600, (s / 60) % 60, s % 60)
}
