    msg: String,
    done: u64,
    total: u64,
    eta_known: bool,
    phase_start: Instant,
}

pub struct Bar {
    enabled: bool,
    width: usize,
    state: Arc<Mutex<State>>,
    running: Arc<std::sync::atomic::AtomicBool>,
    handle: Option<std::thread::JoinHandle<()>>,
}

impl Bar {
    pub fn new(enabled: bool) -> Bar {
        let width = if enabled {
            crate::sys::terminal_size(1).map(|(c, _)| c as usize).unwrap_or(80)
        } else {
            80
        };
        Bar {
            enabled,
            width,
            state: Arc::new(Mutex::new(State {
                msg: String::new(),
                done: 0,
                total: 0,
                eta_known: false,
                phase_start: Instant::now(),
