            handle: None,
        }
    }

    pub fn start_phase(&mut self, msg: &str) {
        if !self.enabled {
            return;
        }
        self.stop();
        {
            let mut s = self.state.lock().unwrap();
            s.msg = msg.to_string();
            s.done = 0;
            s.total = 0;
            s.eta_known = false;
            s.phase_start = Instant::now();
        }
        self.spawn();
        self.draw();
    }

    /// Update the "Current estimate" frame.
    pub fn set_estimate(&mut self, msg: &str, done: u64, total: u64, elapsed: f64) {
        if !self.enabled {
            return;
        }
        let mut s = self.state.lock().unwrap();
        s.msg = msg.to_string();
        s.done = done;
        s.total = total;
        s.eta_known = total > 0 && done > 0 && elapsed > 0.0;
        s.phase_start = Instant::now() - Duration::from_secs_f64(elapsed);
        drop(s);
        self.draw();
    }

    pub fn draw(&self) {
        if !self.enabled {
            return;
        }
        let s = self.state.lock().unwrap().clone();
        let spinner_idx = ((s.phase_start.elapsed().as_millis() as u64 / 80) % 10) as usize;
