                let _ = write!(out, " {} {}{} ETA {} ", spinner, msg_field, bar, eta);
                let _ = write!(out, "\r\u{1b}[2K");
                let _ = out.flush();
            }
        });
        self.handle = Some(handle);
    }

    pub fn stop(&mut self) {
        self.running
            .store(false, std::sync::atomic::Ordering::SeqCst);
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

