{"command": "cd /workspace && cat > src/params.rs <<'RSEOF'
//! Parameter scan / list handling.

use crate::cli::Parameters;

pub enum ParamError {
    InvalidDecimal(&'static str),
    EmptyRange,
    ZeroStep,
    TooLarge,
    MissingStep,
}

pub fn decimal_parse(s: &str) -> Result<(f64, u32), ParamError> {
    if s.is_empty() {
        return Err(ParamError::InvalidDecimal("empty"));
    }
    let bytes: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    let mut neg = false;
    if bytes[0] == '+' || bytes[0] == '-' {
        neg = bytes[0] == '-';
        i = 1;
    }
    if i >= bytes.len() {
        return Err(ParamError::InvalidDecimal("unknown character"));
    }
    let mut int_digits = 0usize;
    let mut frac_digits = 0usize;
    let mut seen_dot = false;
    let mut any = false;
    while i < bytes.len() {
        let c = bytes[i];
        if c == '.' {
            if seen_dot {
                return Err(ParamError::InvalidDecimal("two decimal points"));
            }
            seen_dot = true;
            i += 1;
            continue;
        }
        if c.is_ascii_digit() {
            any = true;
            if seen_dot {
                frac_digits += 1;
            } else {
                int_digits += 1;
            }
            i += 1;
            continue;
        }
        return Err(ParamError::InvalidDecimal("unknown character"));
    }
    if !any {
        return Err(ParamError::InvalidDecimal("unknown character"));
    }
    let val: f64 = s.parse::<f64>().map_err(|_| ParamError::InvalidDecimal("unknown character"))?;
    let _ = (int_digits, frac_digits);
    let decimals = frac_digits as u32;
    Ok((if neg { -val } else { val }, decimals))
}

/// Format a value with `decimals` decimal places, trimming nothing.
fn fmt_fixed(v: f64, decimals: u32) -> String {
    if decimals == 0 {
        // integer: print without decimals, but avoid "-0"
        let r = v.round();
        format!("{}", r as i64)
    } else {
        format!("{:.*}", decimals as usize, v)
    }
}

/// Generate the values of a numeric parameter scan.
pub fn scan_values(
    name: &str,
    min_s: &str,
    max_s: &str,
    step_s: Option<&str>,
) -> Result<Vec<String>, ParamError> {
    let (min, min_dec) = decimal_parse(min_s).map_err(|e| {
        let _ = name;
        e
    })?;
    let (max, max_dec) = decimal_parse(max_s)?;
    let _ = max_dec;
    let min_is_float = min_s.contains('.') || min_s.contains('e') || min_s.contains('E');
    let max_is_float = max_s.contains('.') || max_s.contains('e') || max_s.contains('E');
    let step = match step_s {
        Some(s) => {
            let (v, d) = decimal_parse(s)?;
            if v == 0.0 {
                return Err(ParamError::ZeroStep);
            }
            Some((v, d))
        }
        None => {
            if min_is_float || max_is_float {
                return Err(ParamError::MissingStep);
            }
            None
        }
    };
    match step {
        None => {
            // integer range
            let lo = min as i64;
            let hi = max as i64;
            if hi < lo {
                return Err(ParamError::EmptyRange);
            }
            if ((hi - lo + 1) as f64) > 100000.0 {
                return Err(ParamError::TooLarge);
            }
            let mut out = Vec::new();
            for i in lo..=hi {
                out.push(i.to_string());
            }
            Ok(out)
        }
        Some((step_v, step_dec)) => {
            if max < min {
                return Err(ParamError::EmptyRange);
            }
            let decimals = min_dec.max(step_dec);
            let scale = 10f64.powi(decimals as i32);
            let min_scaled = (min * scale).round() as i64;
            let max_scaled = (max * scale).round() as i64;
            let step_scaled = (step_v * scale).round() as i64;
            if step_scaled <= 0 {
                return Err(ParamError::ZeroStep);
            }
            let span = (max_scaled - min_scaled) as f64 / step_scaled as f64 + 1.0;
            if ((max - min + 1.0) / step_v) > 100000.0 {
                return Err(ParamError::TooLarge);
            }
            let count = span as usize;
            let mut out = Vec::new();
            out.push(fmt_fixed(min, min_dec));
            for i in 1..count {
                let v = (min_scaled + i as i64 * step_scaled) as f64 / scale;
                out.push(fmt_fixed(v, decimals));
            }
            Ok(out)
        }
    }
}

/// Cartesian product of the parameter lists (first list varies fastest).
pub fn combine(lists: &[Parameters]) -> Vec<Vec<(String, String)>> {
    let mut out: Vec<Vec<(String, String)>> = vec![Vec::new()];
    for l in lists {
        let mut next: Vec<Vec<(String, String)>> = Vec::new();
        for combo in &out {
            for v in &l.values {
                let mut c = combo.clone();
                c.push((l.name.clone(), v.clone()));
                next.push(c);
            }
        }
        out = next;
    }
    out
}
RSEOF
echo ok"}

