        if min > max {
            return Err(
                "Conflicting requirements for the number of runs (empty range, min is larger than max)"
                    .to_string(),
            );
        }
    }
    let n_cmds = opts.commands.len();
    if !opts.prepare.is_empty() && opts.prepare.len() != 1 && opts.prepare.len() != n_cmds {
        return Err(format!(
            "The '--prepare' option has to be provided just once or N times, where N={} is the number of benchmark commands (including a potential reference).",
            n_cmds
        ));
    }
    if !opts.conclude.is_empty() && opts.conclude.len() != 1 && opts.conclude.len() != n_cmds {
        return Err(format!(
            "The '--conclude' option has to be provided just once or N times, where N={} is the number of benchmark commands (including a potential reference).",
            n_cmds
        ));
    }
    if opts.output.len() > 1 && opts.output.len() != n_cmds {
        return Err(format!(
            "The '--output' option has to be provided just once or N times, where N={} is the number of benchmark commands (including a potential reference).",
            n_cmds
        ));
    }
    if !opts.command_names.is_empty() && opts.command_names.len() > n_cmds {
        return Err(format!(
            "Too many --command-name options: Expected {} at most",
            n_cmds
        ));
    }
    for i in &opts.input {
        if let InputWhere::File(f) = i {
            if !std::path::Path::new(f).exists() {
                return Err(format!("The file '{}' specified as '--input' does not exist", f));
            }
        }
    }
    for o in &opts.output {
        if let OutputWhere::File(f) = o {
            // A bare word that is not a known policy is treated as an unknown
            // policy, unless it looks like a path.
            if !f.starts_with('.') && !f.starts_with('/') {
                return Err(format!(
                    "Unknown output policy '{}'. Use './{}' to output to a file named '{}'.",
                    f, f, f
                ));
            }
        }
    }

    // ----------------------------------------------------- benchmark list
    let mut benchmarks: Vec<BenchSpec> = Vec::new();
    for (i, cmd) in opts.commands.iter().enumerate() {
        benchmarks.push(BenchSpec {
            cmd: cmd.clone(),
            prepare: nth(&opts.prepare, i),
            conclude: nth(&opts.conclude, i),
            output: nth_out(&opts.output, i),
            input: nth_in(&opts.input, i),
            name_override: opts.command_names.get(i).cloned(),
            params: Vec::new(),
        });
    }

