        if let Some(scan) = &opts.parameter_scan {
            let step = opts.parameter_step_size.as_deref();
            let values = params::scan_values(&scan.name, &scan.values[0], &scan.values[1], step)
                .map_err(param_error)?;
            for v in values {
                let mut b2 = b.clone();
                b2.params = vec![(scan.name.clone(), v)];
                expanded.push(b2);
            }
        } else if !opts.parameter_lists.is_empty() {
            for combo in params::combine(&opts.parameter_lists) {
                let mut b2 = b.clone();
                b2.params = combo;
                expanded.push(b2);
            }
        } else {
            expanded.push(b.clone());
        }
    }

    // reference command
    if let Some(reference) = &opts.reference {
        let mut b = BenchSpec {
            cmd: reference.clone(),
            prepare: None,
            conclude: None,
            output: nth_out(&opts.output, 0),
            input: nth_in(&opts.input, 0),
            name_override: opts.reference_name.clone(),
            params: Vec::new(),
        };
        // apply the parameters that are used inside the reference command
        if !opts.parameter_lists.is_empty() {
            let mut used: Vec<(String, String)> = Vec::new();
            for (k, v) in &expanded.first().map(|b| b.params.clone()).unwrap_or_default() {
                if reference.contains(&format!("{{{}}}", k)) {
                    used.push((k.clone(), v.clone()));
                }
            }
            b.params = used;
        }
        expanded.insert(0, b);
    }

    // --------------------------------------------------------- preparation
    let shell_argv: Vec<String> = match &opts.shell {
        Shell::None => Vec::new(),
        Shell::Default(s) => shlex::split(s).unwrap_or_else(|| vec![s.clone()]),
    };
    let spawn = if shell_argv.is_empty() {
        None
    } else {
        Some(bench::measure_shell_spawn(&shell_argv, &opts).map_err(|e| e)?)
    };

    let interactive = sys::is_terminal(1) && opts.style != Style::Basic && opts.style != Style::Color
