        Style::Full | Style::Color => true,
        Style::Basic | Style::NoColor | Style::None => false,
        Style::Auto => {
            interactive
                && std::env::var("TERM")
                    .map(|t| !t.is_empty() && t != "dumb")
                    .unwrap_or(false)
        }
    };
    let style = ColorStyle {
        color: if colors {
            format::ColorMode::Always
        } else {
            format::ColorMode::Never
        },
    };

    let mut bar = progress::Bar::new(interactive);
    let mut results: Vec<BenchmarkResult> = Vec::new();

    for (idx, spec) in expanded.iter().enumerate() {
        let params_ref: Vec<(String, String)> = spec.params.clone();
        let raw_cmd = bench::substitute(&spec.cmd, &params_ref);
        let used_params: Vec<(String, String)> = params_ref
            .iter()
            .filter(|(k, _)| !raw_cmd.contains(&format!("{{{}}}", k)))
            .cloned()
            .collect();
        let name = match &spec.name_override {
            Some(n) => bench::substitute(n, &params_ref),
            None => {
                if used_params.is_empty() {
                    raw_cmd.clone()
                } else {
                    let parts: Vec<String> = used_params
                        .iter()
                        .map(|(k, v)| format!("{} = {}", k, v))
                        .collect();
                    format!("{} ({})", raw_cmd, parts.join(", "))
                }
            }
        };
        let mut params_with: Vec<(String, String)> = params_ref.clone();
        params_with.extend(spec.params.iter().cloned());

        out::print_header(&style, idx + 1, &name);
        let _ = std::io::stdout().flush();

        // setup
        if let Some(setup) = &opts.setup {
            let c = bench::substitute(setup, &params_ref);
            run_aux(&c, &shell_argv, &InputWhere::Null, &OutputWhere::Null, false)?;
        }
        // warmup
        for _ in 0..opts.warmup {
            if let Some(p) = &spec.prepare {
                let c = bench::substitute(p, &params_ref);
                run_aux(&c, &shell_argv, &InputWhere::Null, &OutputWhere::Null, false)?;
            }
            let c = bench::substitute(&spec.cmd, &params_ref);
            run_aux(&c, &shell_argv, &spec.input, &spec.output, opts.show_output)?;
            if let Some(cc) = &spec.conclude {
                let c = bench::substitute(cc, &params_ref);
                run_aux(&c, &shell_argv, &InputWhere::Null, &OutputWhere::Null, false)?;
            }
        }

        // runs
        let mut timings: Vec<f64> = Vec::new();
        let mut users: Vec<f64> = Vec::new();
        let mut systems: Vec<f64> = Vec::new();
        let mut memory: Vec<u64> = Vec::new();
        let mut exit_codes: Vec<i32> = Vec::new();

        let fixed_runs = opts.runs.is_some();
        let mut target: u64 = 0;
        let mut total_elapsed = 0.0f64;
        let mut run_index = 0u64;

