        let out1 = run_measured(
            &cmd_to_run,
            &shell_argv,
            &spec.input,
            &spec.output,
            opts.show_output,
            &opts,
        )?;
        run_index += 1;
        total_elapsed += out1.time;
        if check_exit(&opts, out1.exit_code, idx == 0, true)? {
