    let unit_opt = opts.time_unit;
    if let Some(p) = &opts.export_csv {
        export::export_csv(p, &results)?;
    }
    if let Some(p) = &opts.export_json {
        export::export_json(p, &results)?;
    }
    if let Some(p) = &opts.export_markdown {
        export::export_markdown(p, &results, unit_opt, opts.sort)?;
    }
    if let Some(p) = &opts.export_asciidoc {
        export::export_asciidoc(p, &results, unit_opt, opts.sort)?;
    }
    if let Some(p) = &opts.export_orgmode {
        export::export_orgmode(p, &results, unit_opt, opts.sort)?;
    }

    // ------------------------------------------------------------- summary
    if results.len() > 1 {
        let names: Vec<String> = results.iter().map(|r| r.name.clone()).collect();
