        systems.push(out1.system);
        memory.push(out1.maxrss);
        exit_codes.push(out1.exit_code);
        run_aux_conclude(&spec.conclude, &params_ref, &shell_argv)?;

        if fixed_runs {
            target = opts.runs.unwrap() as u64;
        } else {
            let est = (3.0f64 / out1.time).floor() as u64;
            target = est.max(opts.min_runs as u64);
            if let Some(m) = opts.max_runs {
                target = target.min(m as u64);
            }
            if target < 1 {
                target = 1;
            }
        }
        while (timings.len() as u64) < target {
            if !fixed_runs {
                let mean = timings.iter().sum::<f64>() / timings.len() as f64;
                bar.set_estimate(
                    &format!("Current estimate: {}", mean_str(&mean, opts.time_unit)),
                    timings.len() as u64,
                    target,
                    total_elapsed,
                );
            }
            if let Some(p) = &spec.prepare {
                let c = bench::substitute(p, &params_ref);
                run_aux(&c, &shell_argv, &InputWhere::Null, &OutputWhere::Null, false)?;
            }
            set_env_iteration(run_index as usize);
            let o = run_measured(
                &cmd_to_run,
                &shell_argv,
                &spec.input,
                &spec.output,
                opts.show_output,
                &opts,
            )?;
            run_index += 1;
            total_elapsed += o.time;
            if check_exit(&opts, o.exit_code, idx == 0, false)? {
                return Err(failure_message(&cmd_to_run, o.exit_code));
            }
            timings.push(o.time);
            users.push(o.user);
            systems.push(o.system);
            memory.push(o.maxrss);
            exit_codes.push(o.exit_code);
            run_aux_conclude(&spec.conclude, &params_ref, &shell_argv)?;
        }
        bar.clear();

        // shell spawn correction
        let (mut times, mut us, mut sy) = if let Some(s) = &spawn {
            (
                timings.iter().map(|t| (t - s.time).max(0.0)).collect::<Vec<f64>>(),
                users.iter().map(|u| (u - s.user).max(0.0)).collect::<Vec<f64>>(),
                systems.iter().map(|t| (t - s.system).max(0.0)).collect::<Vec<f64>>(),
            )
        } else {
            (timings.clone(), users.clone(), systems.clone())
        };
        let (mean, stddev, median, min, max) = bench::compute_stats(times.clone());
        let user_mean = us.iter().sum::<f64>() / us.len() as f64;
        let system_mean = sy.iter().sum::<f64>() / sy.len() as f64;
        let _ = (&mut times, &mut us, &mut sy);

        let non_zero_exit = exit_codes.iter().any(|c| *c != 0);
        let warnings = bench::get_warnings(&times, mean, spawn.is_some(), non_zero_exit);

        let time_unit = match opts.time_unit {
            Some(u) => u,
            None => auto_unit(mean),
        };
        let result = BenchmarkResult {
            name: name.clone(),
            command: name.clone(),
            mean,
            stddev,
            median,
            user: user_mean,
            system: system_mean,
            min,
            max,
            times,
            memory,
            exit_codes,
        };
        out::print_summary(&style, &result, time_unit, timings.len() == 1);
        out::print_warnings(&style, &warnings, &name);

        if let Some(c) = &opts.cleanup {
            let c = bench::substitute(c, &params_ref);
            run_aux(&c, &shell_argv, &InputWhere::Null, &OutputWhere::Null, false)?;
        }
        results.push(result);
    }

    // ------------------------------------------------------------- exports
    let unit_opt = opts.time_unit;
    if let Some(p) = &opts.export_csv {
        export::export_csv(p, &results)?;
    }
    if let Some(p) = &opts.export_json {
        export::export_json(p, &results)?;
    }
    if let Some(p) = &opts.export_markdown {
        export::export_markdown(p, &results, unit_opt, opts.sort)?;
    }
    if let Some(p) = &opts.export_asciidoc {
        export::export_asciidoc(p, &results, unit_opt, opts.sort)?;
    }
    if let Some(p) = &opts.export_orgmode {
        export::export_orgmode(p, &results, unit_opt, opts.sort)?;
    }

    // ------------------------------------------------------------- summary
    if results.len() > 1 {
        let names: Vec<String> = results.iter().map(|r| r.name.clone()).collect();
        if results.iter().any(|r| r.mean <= 0.0) {
            out::print_zero_times_note();
        } else {
            let reference = opts.reference.as_deref().map(|r| {
                results
                    .iter()
                    .position(|x| x.name == r)
                    .map(|i| names[i].clone())
                    .unwrap_or_else(|| r.to_string())
            });
            out::print_summary_section(&style, &results, &names, reference.as_deref(), opts.sort);
        }
    }
    Ok(())
}

fn mean_str(mean: &f64, unit: Option<TimeUnit>) -> String {
    format_time(*mean, unit.unwrap_or_else(|| auto_unit(*mean)))
}

fn set_env_iteration(i: usize) {
    std::env::set_var("HYPERFINE_ITERATION", i.to_string());
}

fn nth<T: Clone>(v: &[T], i: usize) -> Option<T> {
    if v.len() == 1 {
        v.first().cloned()
    } else {
        v.get(i).cloned()
    }
}

fn nth_out(v: &[OutputWhere], i: usize) -> OutputWhere {
    nth(v, i).unwrap_or(OutputWhere::Null)
}
fn nth_in(v: &[InputWhere], i: usize) -> InputWhere {
    nth(v, i).unwrap_or(InputWhere::Null)
}

#[derive(Clone)]
struct BenchSpec {
    cmd: String,
    prepare: Option<String>,
    conclude: Option<String>,
    output: OutputWhere,
    input: InputWhere,
    name_override: Option<String>,
    params: Vec<(String, String)>,
}

fn run_aux(
    cmd: &str,
    shell_argv: &[String],
    input: &InputWhere,
    output: &OutputWhere,
    show: bool,
) -> Result<(), String> {
    run_measured(cmd, shell_argv, input, output, show, &ShellOpts::default())?;
    Ok(())
}
fn run_aux_conclude(
    conclude: &Option<String>,
    params: &[(String, String)],
    shell_argv: &[String],
) -> Result<(), String> {
    if let Some(c) = conclude {
        let c = bench::substitute(c, params);
        run_aux(&c, shell_argv, &InputWhere::Null, &OutputWhere::Null, false)?;
    }
    Ok(())
}

struct ShellOpts {
    ignore: Option<IgnoreFailure>,
}
impl Default for ShellOpts {
    fn default() -> Self {
        ShellOpts { ignore: None }
    }
}

fn run_measured(
    cmd: &str,
    shell_argv: &[String],
    input: &InputWhere,
    output: &OutputWhere,
    show: bool,
    opts: &ShellOpts,
) -> Result<RunOutcome, String> {
    let argv: Vec<String> = if shell_argv.is_empty() {
        match shlex::split(cmd) {
            Some(v) if !v.is_empty() => v,
            _ => return Err("empty command".to_string()),
        }
    } else {
        let mut a = shell_argv.to_vec();
        a.push("-c".to_string());
        a.push(cmd.to_string());
        a
    };
    bench::execute(&argv, input, output, show).map_err(|e| e)
}

fn param_error(e: params::ParamError) -> String {
    match e {
        params::ParamError::InvalidDecimal(what) => {
            format!("Error while parsing parameter scan arguments (Invalid decimal: {})", what)
        }
        params::ParamError::EmptyRange => "Empty parameter range".to_string(),
        params::ParamError::ZeroStep => "Zero is not a valid parameter step".to_string(),
        params::ParamError::TooLarge => "Parameter range is too large".to_string(),
        params::ParamError::MissingStep => "A step size is required when the range bounds are floating point numbers. The step size can be specified with the '-D/--parameter-step-size <DELTA>' parameter".to_string(),
    }
}

/// Returns true when the run failed and the benchmark must be aborted.
fn check_exit(
    opts: &CmdOptions,
    code: i32,
    first_command: bool,
    first_run: bool,
) -> Result<bool, String> {
    if code == 0 {
        return Ok(false);
    }
    match &opts.ignore_failure {
        Some(IgnoreFailure::AllNonZero) => Ok(false),
        Some(IgnoreFailure::Codes(codes)) => {
            if codes.contains(&code) {
                Ok(false)
            } else {
                Ok(true)
            }
        }
        None => Ok(true),
    }
}

fn failure_message(cmd: &str, code: i32) -> String {
    format!(
        "Command terminated with non-zero exit code {} in the first benchmark run. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.",
        code
    )
}
