import subprocess,re,sys
def norm(s):
    s=re.sub(r'\d+\.\d+','X',s)
    s=re.sub(r'\d+','N',s)
    return s
def run(bin,args,timeout=200):
    r=subprocess.run([bin]+args,capture_output=True,text=True,timeout=timeout)
    return r.stdout+r.stderr, r.returncode
def cmp(args,label=None,env=None):
    import os
    e=dict(os.environ); 
    if env: e.update(env)
    a=subprocess.run(['/workspace/executable']+args,capture_output=True,text=True,env=e,timeout=300)
    b=subprocess.run(['/workspace/executable_new']+args,capture_output=True,text=True,env=e,timeout=300)
    oa,ob=norm(a.stdout+a.stderr),norm(b.stdout+b.stderr)
    if oa==ob and a.returncode==b.returncode:
        print("OK   ", label or ' '.join(args))
    else:
        print("DIFF ", label or ' '.join(args), "rc=%d/%d"%(a.returncode,b.returncode))
        la,lb=oa.splitlines(),ob.splitlines()
        import difflib
        for line in list(difflib.unified_diff(la,lb,lineterm=''))[:30]:
            print("   ",line)
