    sort: SortMethod,
) {
    let ref_name = names[ref_idx].clone();
    if sort == SortMethod::Command {
        println!("{}", style.bold("Relative speed comparison"));
        for (i, r) in results.iter().enumerate() {
            let factor = if r.mean >= results[ref_idx].mean {
                r.mean / results[ref_idx].mean
            } else {
                results[ref_idx].mean / r.mean
            };
            let unc = uncertainty_of(r, &results[ref_idx], factor);
            if i == ref_idx {
                println!(
                    "{}          {}",
                    crate::format::right_align("1.00", 12),
                    style.bold(&names[i])
                );
            } else {
                println!(
                    "{} \\u{b1} {}  {}",
                    crate::format::right_align(&format!("{:.2}", factor), 12),
                    crate::format::right_align(&style.green(&format!("{:.2}", unc)), 5),
                    style.bold(&names[i])
                );
            }
        }
        return;
    }
    println!("{}", style.bold("Summary"));
    println!("  {} ran", style.cyan(&ref_name));
    let ref_mean = results[ref_idx].mean;
    let mut order: Vec<usize> = (0..results.len()).filter(|i| *i != ref_idx).collect();
    order.sort_by(|a, b| results[*a].mean.partial_cmp(&results[*b].mean).unwrap());
    for i in order {
        let factor = if results[i].mean >= ref_mean {
            results[i].mean / ref_mean
        } else {
            ref_mean / results[i].mean
        };
        let word = if results[i].mean >= ref_mean {
            "faster"
        } else {
            "slower"
        };
        let unc = uncertainty_of(&results[i], &results[ref_idx], factor);
        if unc > 0.0 {
