import os,pty,sys,time,select,fcntl,termios,struct
def run(cmd, cols=120, rows=30, wait=6.0, env=None):
    pid, fd = pty.fork()
    try: fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    except Exception: pass
    e=dict(os.environ); e['TERM']='xterm-256color'
    if env: e.update(env)
    os.write(fd, cmd.encode())
    out=b''
    t0=time.time()
    while time.time()-t0 < wait:
        r,_,_=select.select([fd],[],[],0.2)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d
    try: os.close(fd)
    except Exception: pass
    try: os.waitpid(pid,0)
    except Exception: pass
    return out.decode('utf8',errors='replace')
if __name__=='__main__':
    for cols in [80,120,60]:
        for b,label in [('/workspace/executable','ORIG'),('/tmp/cmpdir/executable','MINE')]:
            out=run("exec %s -r 2 'sleep 0.3'\n" % b, cols=cols)
            i=out.find('Initial time measurement')
            if i<0: print(cols,label,'no frame'); continue
            # find a frame line
            line=out[i-3:i+150]
            print("cols=%-4d %-5s %r" % (cols,label,line.replace('\r','|')[:140]))
